"""Piecewise polynomials over the octaves of the argument.

    uv run --with mpmath==1.4.1 python testdata/gen/fit_octaves.py NAME > zz_NAME_coeffs.go

Each octave [2^e, 2^(e+1)) of x, for EMIN <= e <= EMAX, is cut into NSUB
pieces of equal width; on each, f is interpolated at Chebyshev nodes
(fit.cheb_interp, 200 bits) with a fixed degree DEG and converted to
monomials in s = x - c, c the piece centre (an exact float64, and x - c is
exact by Sterbenz's lemma). The interpolation interval is widened by 2^-20
of its width on both sides. The constant term is also emitted as a
double-double (c0lo) so that callers can evaluate c0 + (s q(s) + c0lo) with
a single rounding. The maximum interpolation error over all pieces, checked
on 201 points each against mpmath, is printed in the header; generation
fails above 2^-60 relative.
"""

import sys

import mpmath
from mpmath import mp, mpf

from fit import cheb_interp

mp.prec = 200


def i0e(x):
    with mp.workprec(mp.prec + 40):
        return mp.besseli(0, x) * mp.exp(-x)


def k0e(x):
    with mp.workprec(mp.prec + 40):
        return mp.besselk(0, x) * mp.exp(x)


# name: (doc, f, EMIN, EMAX, NSUB, DEG)
JOBS = {
    "besselI0eOct": ("I0(x) e^-x for x in [2^-3, 2^9).", i0e, -3, 8, 8, 11),
    "besselK0eOct": ("K0(x) e^x for x in [1, 2^9).", k0e, 0, 8, 8, 11),
}


def main(name):
    doc, f, emin, emax, nsub, deg = JOBS[name]
    rows = []
    worst = mpf(0)
    for e in range(emin, emax + 1):
        x0 = mpf(2) ** e
        for j in range(nsub):
            a = x0 * (1 + mpf(j) / nsub)
            b = x0 * (1 + mpf(j + 1) / nsub)
            pad = (b - a) * mpf(2) ** -20
            c, co = cheb_interp(f, a - pad, b + pad, deg)
            assert c == (a + b) / 2 and c == mpf(float(c))
            for k in range(201):
                t = a + (b - a) * k / 200
                pv = mp.fsum(co[i] * (t - c) ** i for i in range(len(co)))
                fv = f(t)
                worst = max(worst, abs((pv - fv) / fv))
            rows.append((e, j, c, co))
    if worst > mpf(2) ** -60:
        raise SystemExit("%s: interpolation error %s" % (name, mpmath.nstr(worst, 3)))
    print("// Code generated by testdata/gen/fit_octaves.py %s; DO NOT EDIT." % name)
    print("//")
    print("// %s: %s" % (name, doc))
    print("// Degree %d on %d pieces per octave of x in [2^%d, 2^%d), in s = x - c;" % (deg, nsub, emin, emax + 1))
    print("// max interpolation error %s relative (mpmath %s, 200 bits)." % (mpmath.nstr(worst, 3), mpmath.__version__))
    print()
    print("package special")
    print()
    print("var %s = [...]octPiece{" % name)
    for e, j, c, co in rows:
        c0lo = float(co[0] - mpf(float(co[0])))
        print("\t// x in 2^%d * [%d/%d, %d/%d]" % (e, nsub + j, nsub, nsub + j + 1, nsub))
        print("\t{c: %r, c0lo: %r, coef: [...]float64{" % (float(c), c0lo))
        print("\t\t" + ", ".join(repr(float(v)) for v in reversed(co)) + ",")
        print("\t}},")
    print("}")


if __name__ == "__main__":
    main(sys.argv[1])
